declarations.formal_type:
∀ {k : Type u_1} [inst : Field.{u_1} k] {V : Type u_2} [inst_1 : AddCommGroup.{u_2} V] [inst_2 : Module.{u_1, u_2} k V]
  {N : Nat} (b : Module.Basis.{0, u_1, u_2} (Fin N) k V) (A : LinearMap.{u_1, u_1, u_2, u_2} (RingHom.id.{u_1} k) V V),
  (∀ (j : Fin N),
      Membership.mem.{u_2, u_2}
        (Submodule.span.{u_1, u_2} k
          (Set.image.{0, u_2} (DFunLike.coe.{max (u_1 + 1) (u_2 + 1), 1, u_2 + 1} b) (Set.Iic.{0} j)))
        (DFunLike.coe.{u_2 + 1, u_2 + 1, u_2 + 1} A (DFunLike.coe.{max (u_1 + 1) (u_2 + 1), 1, u_2 + 1} b j))) →
    Matrix.BlockTriangular.{u_1, 0, 0}
      (DFunLike.coe.{max (u_1 + 1) (u_2 + 1), u_2 + 1, u_1 + 1} (LinearMap.toMatrix.{u_1, 0, 0, u_2, u_2} b b) A) id.{1}

∀ {k : Type u} [inst : Field.{u} k] {V : Type v} [inst_1 : AddCommGroup.{v} V] [inst_2 : Module.{u, v} k V]
  [Module.Finite.{u, v} k V] [IsAlgClosed.{u} k] {N : Nat} (A : LinearMap.{u, u, v, v} (RingHom.id.{u} k) V V),
  Eq.{1} (Module.finrank.{u, v} k V) N →
    Exists.{max (u + 1) (v + 1)} fun b =>
      Matrix.BlockTriangular.{u, 0, 0}
        (DFunLike.coe.{max (u + 1) (v + 1), v + 1, u + 1} (LinearMap.toMatrix.{u, 0, 0, v, v} b b) A) id.{1}

∀ {k : Type u_1} [inst : Field.{u_1} k] {N : Nat} {lam mu : Fin N → k},
  Eq.{u_1 + 1}
      (Finset.prod.{0, u_1} Finset.univ.{0} fun i =>
        HSub.hSub.{u_1, u_1, u_1} Polynomial.X.{u_1}
          (DFunLike.coe.{u_1 + 1, u_1 + 1, u_1 + 1} Polynomial.C.{u_1} (lam i)))
      (Finset.prod.{0, u_1} Finset.univ.{0} fun i =>
        HSub.hSub.{u_1, u_1, u_1} Polynomial.X.{u_1}
          (DFunLike.coe.{u_1 + 1, u_1 + 1, u_1 + 1} Polynomial.C.{u_1} (mu i))) →
    Exists.{1} fun e => ∀ (i : Fin N), Eq.{u_1 + 1} (lam i) (mu (DFunLike.coe.{1, 1, 1} e i))

∀ {k : Type u_1} [inst : Field.{u_1} k] {ι : Type u_2} [inst_1 : Fintype.{u_2} ι] (f : ι → k),
  Eq.{u_1 + 1}
    (Polynomial.roots.{u_1}
      (Finset.prod.{u_2, u_1} Finset.univ.{u_2} fun i =>
        HSub.hSub.{u_1, u_1, u_1} Polynomial.X.{u_1}
          (DFunLike.coe.{u_1 + 1, u_1 + 1, u_1 + 1} Polynomial.C.{u_1} (f i))))
    (Multiset.map.{u_1, u_2} f (Finset.val.{u_2} Finset.univ.{u_2}))
